    elif hminor is None:
        result.append(("<", _v(hmajor + 1, 0, 0)))
    elif hpatch is None:
        result.append(("<", _v(hmajor, hminor + 1, 0)))
    else:
        result.append(("<=", _v(hmajor, hminor, hpatch, hpre)))
    return result


def _parse_set(text):
    text = text.strip()
    if not text:
        return []
